#!/usr/bin/env bash
# Context probe shared by the ep-* skills.
#
# Source of truth: shared/context.sh. Copies in skills/*/scripts/ are generated by
# scripts/sync-shared.sh; edit this file, not the copies.
#
# Usage: context.sh [pr-number]
#
# Prints one JSON object:
#   { "git":      { branch, upstream, ahead, behind, dirty, staged_files,
#                   unstaged_files, default_branch },
#     "pr":       { number, url, state, isDraft, mergeStateStatus, reviewDecision,
#                   checks: [{ name, status, conclusion }] } | null,
#     "openspec": { root, changes: [{ name, tasks_done, tasks_total }] } | null,
#     "warnings": [ ... ] }
#
# ahead/behind are relative to the upstream and are null when there is no upstream.
# pr is null when gh is missing, unauthenticated, or no PR exists for the branch.
# openspec is null when the openspec CLI is missing or the repo has no OpenSpec root.
# Requires git. gh and openspec are optional. jq is not used.

set -u

warnings=()

json_str() {
  # Print $1 as a JSON string literal.
  local s=$1 out="" c i code
  for ((i = 0; i < ${#s}; i++)); do
    c=${s:i:1}
    case $c in
      '"') out+='\"' ;;
      '\') out+='\\' ;;
      $'\n') out+='\n' ;;
      $'\r') out+='\r' ;;
      $'\t') out+='\t' ;;
      *)
        printf -v code '%d' "'$c"
        if ((code >= 0 && code < 32)); then
          printf -v c '\\u%04x' "$code"
        fi
        out+=$c
        ;;
    esac
  done
  printf '"%s"' "$out"
}

json_str_or_null() {
  if [ -n "$1" ]; then json_str "$1"; else printf 'null'; fi
}

json_array_from_lines() {
  # Print the non-empty lines of $1 as a JSON array of strings.
  local first=1 line
  printf '['
  while IFS= read -r line; do
    [ -z "$line" ] && continue
    if ((first)); then first=0; else printf ','; fi
    json_str "$line"
  done <<<"$1"
  printf ']'
}

if ! git rev-parse --is-inside-work-tree >/dev/null 2>&1; then
  printf '{"error":"not a git repository"}\n'
  exit 1
fi

# --- git -------------------------------------------------------------------

branch=$(git symbolic-ref --quiet --short HEAD 2>/dev/null || true)
upstream=$(git rev-parse --abbrev-ref --symbolic-full-name '@{u}' 2>/dev/null || true)

ahead=null
behind=null
if [ -n "$upstream" ]; then
  if counts=$(git rev-list --left-right --count '@{u}...HEAD' 2>/dev/null); then
    behind=${counts%%[[:space:]]*}
    ahead=${counts##*[[:space:]]}
  fi
fi

# -z avoids git's C-style quoting of unusual paths.
staged=$(git diff --cached --name-only -z 2>/dev/null | tr '\0' '\n' || true)
unstaged=$(
  {
    git diff --name-only -z 2>/dev/null
    git ls-files --others --exclude-standard -z 2>/dev/null
  } | tr '\0' '\n' | sort -u
)
if [ -n "$staged$unstaged" ]; then dirty=true; else dirty=false; fi

default_branch=$(git symbolic-ref --quiet --short refs/remotes/origin/HEAD 2>/dev/null || true)
default_branch=${default_branch#origin/}

# --- gh / PR ---------------------------------------------------------------

pr_json=null
gh_ok=0
if command -v gh >/dev/null 2>&1; then
  if gh auth status >/dev/null 2>&1; then
    gh_ok=1
  else
    warnings+=("gh is not authenticated; pr is null")
  fi
else
  warnings+=("gh not found; pr is null")
fi

if ((gh_ok)) && [ -z "$default_branch" ]; then
  default_branch=$(gh repo view --json defaultBranchRef --jq '.defaultBranchRef.name' 2>/dev/null || true)
fi

if ((gh_ok)); then
  pr_args=()
  [ $# -ge 1 ] && [ -n "$1" ] && pr_args=("$1")
  if [ ${#pr_args[@]} -gt 0 ] || [ -n "$branch" ]; then
    pr_out=$(gh pr view "${pr_args[@]}" \
      --json number,url,state,isDraft,mergeStateStatus,reviewDecision,statusCheckRollup \
      --jq '{number, url, state, isDraft, mergeStateStatus,
             reviewDecision: (if .reviewDecision == "" then null else .reviewDecision end),
             checks: [(.statusCheckRollup // [])[] | {
               name: (.name // .context),
               status: (.status // .state),
               conclusion: (if .__typename == "StatusContext" then .state
                            else (.conclusion | if . == "" then null else . end) end)
             }]}' 2>/dev/null) && [ -n "$pr_out" ] && pr_json=$pr_out
  fi
fi

if [ -z "$default_branch" ]; then
  for b in main master; do
    if git show-ref --verify --quiet "refs/heads/$b" || git show-ref --verify --quiet "refs/remotes/origin/$b"; then
      default_branch=$b
      warnings+=("default branch guessed as $b")
      break
    fi
  done
fi

# --- openspec --------------------------------------------------------------

openspec_json=null
if command -v openspec >/dev/null 2>&1; then
  # openspec list exits non-zero with "root": null when there is no OpenSpec root.
  os_out=$(openspec list --json 2>/dev/null || true)
  if [ -n "$os_out" ]; then
    # Flatten the JSON so it can be parsed line by line without jq.
    flat=$(printf '%s' "$os_out" | tr -d '\n')
    root=$(printf '%s' "$flat" | sed -n 's/.*"root"[[:space:]]*:[[:space:]]*{[^}]*"path"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p')
    if [ -n "$root" ]; then
      changes=$(printf '%s' "$flat" | grep -o '{[^{}]*"name"[^{}]*}' || true)
      out='['
      first=1
      while IFS= read -r ch; do
        [ -z "$ch" ] && continue
        name=$(printf '%s' "$ch" | sed -n 's/.*"name"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p')
        done_n=$(printf '%s' "$ch" | sed -n 's/.*"completedTasks"[[:space:]]*:[[:space:]]*\([0-9]*\).*/\1/p')
        total_n=$(printf '%s' "$ch" | sed -n 's/.*"totalTasks"[[:space:]]*:[[:space:]]*\([0-9]*\).*/\1/p')
        [ -z "$name" ] && continue
        if ((first)); then first=0; else out+=','; fi
        out+="{\"name\":$(json_str "$name"),\"tasks_done\":${done_n:-0},\"tasks_total\":${total_n:-0}}"
      done <<<"$changes"
      out+=']'
      openspec_json="{\"root\":$(json_str "$root"),\"changes\":$out}"
    fi
  fi
fi

# --- output ----------------------------------------------------------------

warn_lines=""
for w in "${warnings[@]+"${warnings[@]}"}"; do warn_lines+="$w"$'\n'; done

printf '{"git":{"branch":%s,"upstream":%s,"ahead":%s,"behind":%s,"dirty":%s,"staged_files":%s,"unstaged_files":%s,"default_branch":%s},"pr":%s,"openspec":%s,"warnings":%s}\n' \
  "$(json_str_or_null "$branch")" \
  "$(json_str_or_null "$upstream")" \
  "$ahead" "$behind" "$dirty" \
  "$(json_array_from_lines "$staged")" \
  "$(json_array_from_lines "$unstaged")" \
  "$(json_str_or_null "$default_branch")" \
  "$pr_json" "$openspec_json" \
  "$(json_array_from_lines "$warn_lines")"
